(* [comment removed for export] *)
Lemma mb_b12_in : forall b es insz n x, mb_ok es insz -> 1 <= n ->
  (exists x' s', In (x', s') (mb_put_es es insz n x) /\ x' + 24 <= fst (mb_b1 b es insz n x) /\ fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x) <= x' + 24 + s')
  /\ (exists x' s', In (x', s') (mb_put_es es insz n x) /\ x' + 24 <= fst (mb_b2 b es insz n x) /\ fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x) <= x' + 24 + s').
Proof.
  intros b es insz n x OK N1. pose proof (mb_ok_bounds _ _ OK) as [IB CB0].
  unfold mb_b2, mb_b1. destruct (mb_need es insz n) eqn:ND; [destruct (mb_full es insz) eqn:FU|]; cbn [andb negb fst snd].
  - destruct (mb_shape_full b es insz n x OK N1 FU) as (_ & EES & EINS & _ & EMO & EOP & EOE & NG & I0).
    split; (exists x, (mb_grow es insz n); rewrite EES; split; [apply in_app_iff; right; left; reflexivity| clear -NG; lia]).
  - destruct (mb_shape_part b es insz n x OK N1 FU ND) as (P & xl & sl & EesP & EES & _ & EMO & ELA & ELS & ECI & EOP & OP1 & OPS & NGT & EOE & OEG & CP0).
    rewrite ELA, EOP, EES. split.
    + exists xl, sl. split; [rewrite EesP; apply in_app_iff; left; apply in_app_iff; right; left; reflexivity|]. rewrite EesP, mb_cap_snoc. clear -OP1 OPS; lia.
    + exists x, (mb_grow es insz n). split; [apply in_app_iff; right; left; reflexivity|]. unfold mb_grow. rewrite EesP, !mb_cap_snoc. clear -OPS NGT; lia.
  - destruct (mb_shape_noneed b es insz n OK N1 ND) as (P & xl & sl & EesP & FU & _ & _ & ELA & ELS & ECI & EOP & OP1 & OPN & EOE & CP0).
    rewrite ELA, EOP. assert (EES : mb_put_es es insz n x = es) by (unfold mb_put_es; rewrite ND; reflexivity). rewrite EES.
    split; (exists xl, sl; split; [rewrite EesP; apply in_app_iff; right; left; reflexivity| clear -OP1 OPN; lia]).
Qed.

Lemma mb_b12_len : forall b es insz n x, mb_ok es insz -> 1 <= n -> 1 <= snd (mb_b1 b es insz n x) /\ 1 <= snd (mb_b2 b es insz n x).
Proof.
  intros b es insz n x OK N1. pose proof (mb_ok_bounds _ _ OK) as [IB _].
  unfold mb_b2, mb_b1. destruct (mb_need es insz n) eqn:ND; [destruct (mb_full es insz) eqn:FU|]; cbn [andb negb fst snd]; unfold mb_need in ND.
  - lia.
  - apply Z.ltb_lt in ND. unfold mb_full in FU. apply Z.eqb_neq in FU. lia.
  - lia.
Qed.

