Definition put_locals2 (ff R out b : Z) (j0 j40 : list byte) : list cell :=
  [CB 16 j0; C8 (wz ff); C8 (wz (R + 8)); C8 (wz out); CB 8 j40; C8 (wz (R + 8)); C8 (wz (b + 8))].

(* [comment removed for export] *)
Definition put_backW (lo spa b : Z) (es : list mbe) (insz n x ff fp : Z) : list (Z * Z) :=
  [(lo, spa + 64);
   (fst (mb_b1 b es insz n x), fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x));
   (fst (mb_b2 b es insz n x), fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x));
   (b + 24, b + 64); (ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z.
