Lemma put_back : forall (Q : machine_state -> Prop) (m : mem) (sp : word) (spa lo shi ff fp rd cbp E src b : Z) (es : list mbe) (insz n x : Z) (bs : list byte)
    (LF : list fframe) (LB : list block) (s : as_St H) (m0 : mem) (gap : list cell)
    (j0 j24 h80 p7 : list byte) (s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (pcv gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  (pcv = Z_to_bv 64 P_A_PUT_RET1 \/ pcv = ret_pc (Z_to_bv 64 P_A_PUT_RET1)) ->
  rw_cells asegs m spa (put_locals1 ff j0 j24) ->
  rw_cells asegs m (spa + 64) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 64) ->
  rw_cells asegs m (bv_unsigned sp + -96) (put_saves s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav) ->
  rw_cells asegs m ff (put_ffa spa) ->
  rw_cells asegs m (ff + 32) (OptSrCells p7 b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n)) ->
  rw_cells asegs m (ff + 80) [CB 40 h80; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs m (Z.shiftr ff 3 + 2147450880) put_sh1 -> rw_cells asegs m fp [C1 (b8 1)] -> accessible m (ff + 32) 48 ->
  rw_cells asegs m rd [C8 (wz b)] -> rd mod 8 = 0 -> accessible m rd 8 -> aapp rd 8 -> (rd + 8 <= ff \/ ff + 128 <= rd) -> (rd + 8 <= fp \/ fp + 1 <= rd) ->
  mb_off b (mb_put_es es insz n x) rd 8 ->
  rw_cells asegs m E (ErrCodeCells EC_clear) -> E mod 8 = 0 -> accessible m E 24 -> aapp E 24 -> (E + 24 <= ff \/ ff + 128 <= E) -> (E + 24 <= fp \/ fp + 1 <= E) ->
  mb_off b (mb_put_es es insz n x) E 24 ->
  rw_cells asegs m cbp [C8 (wz src); C8 (wz n)] -> bv_unsigned sp <= cbp -> cbp + 16 <= shi -> cbp mod 8 = 0 ->
  bytes_at asegs m src bs -> zlength bs = n -> accessible m src n -> shvis m src (src + n) -> aapp src n ->
  (src + n <= ff \/ ff + 128 <= src) -> (src + n <= fp \/ fp + 1 <= src) -> mb_off b (mb_put_es es insz n x) src n ->
  AMBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^26 -> shvis m b (b + 64) ->
  shvis m (fst (mb_b1 b es insz n x)) (fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x)) ->
  shvis m (fst (mb_b2 b es insz n x)) (fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x)) ->
  (b + 64 <= ff \/ ff + 128 <= b) -> (b + 64 <= fp \/ fp + 1 <= b) ->
  (forall x' s', In (x', s') (mb_put_es es insz n x) -> x' + mb_block_size s' <= ff \/ ff + 128 <= x') ->
  (forall x' s', In (x', s') (mb_put_es es insz n x) -> x' + mb_block_size s' <= fp \/ fp + 1 <= x') ->
  bv_unsigned sp + -176 <= spa <= bv_unsigned sp + -160 -> spa mod 32 = 0 ->
  stk asegs m lo spa -> lo + 176 + MB_BCOPY_STACK <= bv_unsigned sp -> aceil <= lo -> mem_inv asegs m ->
  as_RFS H ((1, ff, fp) :: LF) m -> fresh_frame H LF 1 ff fp -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  as_RHEAP H s LB m0 -> aobj LB LF b 64 -> AMBufOwn LB (mb_put_es es insz n x) ->
  bv_unsigned rav mod 2 = 0 ->
  (forall (m' : mem) (y0 y1 y2 c1 c2 c3 c4 c5 c6 c7 y3 y4 y5 y6 : word),
     munch (put_backW lo spa b es insz n x ff fp) m m' -> wmono asegs m m' -> mem_inv asegs m' ->
     stk asegs m' lo (bv_unsigned sp) -> as_RFS H LF m' -> ACONST m' -> stack0 m' lo shi ->
     AMBuf m' b (mb_put_es es insz n x) (insz + n) ->
     rw_cells asegs m' rd [C8 (wz b)] -> rw_cells asegs m' E (ErrCodeCells EC_clear) -> rw_cells asegs m' cbp [C8 (wz src); C8 (wz n)] ->
     bytes_at asegs m' src bs -> accessible m' E 24 -> accessible m' src n ->
     evt asegs Q (MS (mkR rav sp gp tp y0 y1 y2 s0v s1v (wz n) c1 c2 c3 c4 c5 c6 c7 s2v s3v s4v s5v s6v s7v s8v s9v s10v s11 y3 y4 y5 y6)
                     F (ret_pc rav) fc None m' (seg_rom asegs))) ->
  evt asegs Q (MS (mkR (Z_to_bv 64 P_A_PUT_RET1) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
                      (Z_to_bv 64 ff) (Z_to_bv 64 rd) (Z_to_bv 64 E) (Z_to_bv 64 cbp) (Z_to_bv 64 (ff + 32))
                      (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880)
                      (Z_to_bv 64 (Z.shiftr rd 3 + 2147450880)) s11 t3 t4 t5 t6)
